function CourseDetailsPage() {
  const { id } = useParams(); // Get course ID from URL
  const navigate = useNavigate();

  // Find the course from all year categories
  let selectedCourse = null;
  for (const year in courses) {
    selectedCourse = courses[year].find((course) => course.id === parseInt(id));
    if (selectedCourse) break;
  }

  if (!selectedCourse) {
    return <h2>❌ Course Not Found!</h2>;
  }
  const handleRegistration = () => {
    navigate(`/register/${id}`); // Redirect to the registration page
  };


  return (
    <div className="course-details-container">
      <button className="back-button" onClick={() => navigate(-1)}>⬅ Back</button>
      <h1>{selectedCourse.title}</h1>
      <img src={selectedCourse.image} alt={selectedCourse.title} className="course-image" />
      <p className="course-description">{selectedCourse.description}</p>
      {/* Additional Information */}
      <div className="additional-info">
        <h2>What You Will Learn</h2>
        <ul>
          <li>Concept 1</li>
          <li>Concept 2</li>
          <li>Concept 3</li>
          <li>Concept 4</li>
        </ul>

        <h2>Prerequisites</h2>
        <ul>
          <li>Basic Knowledge of X</li>
          <li>Understanding of Y</li>
        </ul>
      </div>
      <button className="enroll-button" onClick={handleRegistration}>Start Course</button>
    </div>
  );
}

export default CourseDetailsPage;
